from dispatch.entity.service import find_entities
from dispatch.entity_type.models import EntityType
from dispatch.signal.redaction import MASK


def test_masked_values_do_not_become_entities(session, signal_instance, project):
    # "api_key" is one of the default redacted fields, so its value is masked before matching
    signal_instance.raw = {
        "events": [
            {"api_key": "ghp_first_secret", "name": "alice"},
            {"api_key": "ghp_second_secret", "name": "bob"},
        ]
    }
    entity_types = [
        EntityType(
            name="Access Token",
            jpath="events[*].api_key",
            regular_expression=None,
            project=project,
        ),
    ]

    entities = find_entities(session, signal_instance, entity_types)

    assert entities == []
    assert all(entity.value != MASK for entity in entities)


def test_unmasked_values_still_become_entities(session, signal_instance, project):
    signal_instance.raw = {
        "events": [
            {"api_key": "ghp_first_secret", "name": "alice"},
            {"api_key": "ghp_second_secret", "name": "bob"},
        ]
    }
    entity_types = [
        EntityType(
            name="User",
            jpath="events[*].name",
            regular_expression=None,
            project=project,
        ),
    ]

    entities = find_entities(session, signal_instance, entity_types)

    assert {entity.value for entity in entities} == {"alice", "bob"}

